begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('71000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'applications-sql-'||n||'@example.invalid',jsonb_build_object('username','Applications_SQL'||n) from generate_series(1,9) n;
insert into auth.sessions(id,user_id) select id,id from public.profiles where id::text like '71000000-%';
update private.authz set role='critic' where user_id='71000000-0000-0000-0000-000000000003';
update private.authz set role='moderator' where user_id='71000000-0000-0000-0000-000000000004';
update private.authz set role='admin' where user_id='71000000-0000-0000-0000-000000000005';
update private.authz set role='critic',critic_verified=true where user_id='71000000-0000-0000-0000-000000000006';
create function pg_temp.app(n integer,op text,input jsonb) returns jsonb language sql as $$ select private.critic_application_operation(('71000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('71000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,op,input); $$;
create function pg_temp.evidence() returns jsonb language sql as $$select jsonb_build_object('organization','Independiente','experience',repeat('🦊',40),'sample',repeat('M',40),'links',jsonb_build_array('https://example.com/evidence'));$$;
create function pg_temp.decision(n integer, outcome text) returns jsonb language sql as $$ select jsonb_build_object('id',id,'version',version,'decision',outcome,'reason','Decisión humana motivada') from private.critic_applications where user_id=('71000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid and status='pending'; $$;
select throws_ok($$select pg_temp.app(4,'submit',pg_temp.evidence())$$,'42501',null,'ineligible role 4');
select throws_ok($$select pg_temp.app(5,'submit',pg_temp.evidence())$$,'42501',null,'ineligible role 5');
select throws_ok($$select pg_temp.app(6,'submit',pg_temp.evidence())$$,'42501',null,'ineligible role 6');
select lives_ok($$select pg_temp.app(1,'submit',pg_temp.evidence())$$,'eligible role 1');
select lives_ok($$select pg_temp.app(3,'submit',pg_temp.evidence())$$,'eligible role 3');
select throws_ok($$select pg_temp.app(1,'submit',pg_temp.evidence())$$,'23505',null,'only one pending');
select is((select role::text from private.authz where user_id='71000000-0000-0000-0000-000000000001'),'user'::text,'submission grants no authority');
select throws_ok($$select pg_temp.app(1,'admin-queue','{"page":1}')$$,'42501',null,'queue forbidden role 1');
select throws_ok($$select pg_temp.app(2,'admin-queue','{"page":1}')$$,'42501',null,'queue forbidden role 2');
select throws_ok($$select pg_temp.app(3,'admin-queue','{"page":1}')$$,'42501',null,'queue forbidden role 3');
select throws_ok($$select pg_temp.app(4,'admin-queue','{"page":1}')$$,'42501',null,'queue forbidden role 4');
select is((select (pg_temp.app(2,'own-history','{"page":1}')->>'total')::int),0,'third party history isolated');
select throws_ok($$select pg_temp.app(1,'resolve',pg_temp.decision(1,'approved'))$$,'42501',null,'resolution denied role 1');
select throws_ok($$select pg_temp.app(3,'resolve',pg_temp.decision(1,'approved'))$$,'42501',null,'resolution denied role 3');
select throws_ok($$select pg_temp.app(4,'resolve',pg_temp.decision(1,'approved'))$$,'42501',null,'resolution denied role 4');
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(1,'approved')||'{"version":2}')$$,'23505',null,'obsolete version denied');
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(1,'approved')||'{"role":"admin"}')$$,'22023',null,'metadata escalation denied');
create function pg_temp.fail_application() returns trigger language plpgsql as $$begin if coalesce(to_jsonb(new)->>'user_id',to_jsonb(new)->>'target_id') like '71000000-%' then raise exception 'forced failure'; end if; return new; end;$$;
create trigger fail_application before insert on private.audit_logs for each row execute function pg_temp.fail_application();
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(1,'approved'))$$,'P0001',null,'private.audit_logs failure aborts');
select is((select role::text from private.authz where user_id='71000000-0000-0000-0000-000000000001'),'user'::text,'authority rolled back');
select is((select count(*)::int from private.application_notices where user_id::text like '71000000-%'),0,'notice rollback');
drop trigger fail_application on private.audit_logs;drop function pg_temp.fail_application();
create function pg_temp.fail_application() returns trigger language plpgsql as $$begin if coalesce(to_jsonb(new)->>'user_id',to_jsonb(new)->>'target_id') like '71000000-%' then raise exception 'forced failure'; end if; return new; end;$$;
create trigger fail_application before insert on private.application_notices for each row execute function pg_temp.fail_application();
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(1,'approved'))$$,'P0001',null,'private.application_notices failure aborts');
select is((select role::text from private.authz where user_id='71000000-0000-0000-0000-000000000001'),'user'::text,'authority rolled back');
select is((select count(*)::int from private.application_notices where user_id::text like '71000000-%'),0,'notice rollback');
drop trigger fail_application on private.application_notices;drop function pg_temp.fail_application();
insert into public.manual_games(id,title,synopsis,platforms,genres,source_url,source_label) values('71000000-0000-0000-0000-000000000099','Isolated application history','Isolated SQL application history fixture only.',array['PC'],array['Test'],'https://example.com/application-history','Isolated SQL fixture');
insert into public.reviews(author_id,manual_game_id,rating,title,body_public,author_active) values('71000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000099',7,'Historia ordinaria','Texto ordinario publicado antes de la admisión.',true);
select lives_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(1,'approved'))$$,'admission succeeds');
select is((select kind from public.reviews where author_id='71000000-0000-0000-0000-000000000001'),'user'::text,'approval preserves historical review kind');
select ok((select critic_verified from public.reviews where author_id='71000000-0000-0000-0000-000000000001'),'approval propagates actual seal');
select is((select critic_verified and role='critic' from private.authz where user_id='71000000-0000-0000-0000-000000000001'),true,'role and seal granted together');
select is((select count(*)::int from private.application_notices where user_id::text like '71000000-%'),1,'one persisted notice');
select throws_ok($$select pg_temp.app(2,'markRead',jsonb_build_object('id',(select id from private.application_notices where user_id='71000000-0000-0000-0000-000000000001' limit 1)))$$,'42501',null,'notice IDOR denied');
update private.authz set status='suspended' where user_id='71000000-0000-0000-0000-000000000001';
select lives_ok($$select pg_temp.app(1,'own-notices','{"page":1}')$$,'suspended own notices readable');
select lives_ok($$select pg_temp.app(1,'markRead',jsonb_build_object('id',(select id from private.application_notices where user_id='71000000-0000-0000-0000-000000000001' limit 1)))$$,'suspended notice mark read');
select throws_ok($$select pg_temp.app(1,'own-history','{"page":1}')$$,'42501',null,'suspended evidence denied');
delete from auth.sessions where id='71000000-0000-0000-0000-000000000001';
select throws_ok($$select pg_temp.app(1,'own-notices','{"page":1}')$$,'42501',null,'revoked notices denied');
update private.authz set status='suspended' where user_id='71000000-0000-0000-0000-000000000003';
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(3,'approved'))$$,'23505',null,'suspension prevents resolve');
select throws_ok($$select pg_temp.app(5,'cancel',pg_temp.decision(3,'approved')-'decision')$$,'23505',null,'suspension prevents cancel');
update private.authz set status='active',critic_verified=true where user_id='71000000-0000-0000-0000-000000000003';
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(3,'approved'))$$,'23505',null,'changed seal blocks approval');
select lives_ok($$select pg_temp.app(5,'cancel',pg_temp.decision(3,'approved')-'decision')$$,'changed seal allows motivated cancellation');
update private.authz set critic_verified=false where user_id='71000000-0000-0000-0000-000000000003';
select lives_ok($$select pg_temp.app(3,'submit',pg_temp.evidence())$$,'cancellation releases pending without cooldown');
select lives_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(3,'rejected'))$$,'reject eligible critic');
select throws_ok($$select pg_temp.app(3,'submit',pg_temp.evidence())$$,'23505',null,'rejection cooldown');
update private.critic_applications set created_at=clock_timestamp()-interval '8 days',resolved_at=clock_timestamp()-interval '168 hours'+interval '5 seconds' where user_id='71000000-0000-0000-0000-000000000003' and status='rejected';
select throws_ok($$select pg_temp.app(3,'submit',pg_temp.evidence())$$,'23505',null,'before full seven days denied');
update private.critic_applications set resolved_at=clock_timestamp()-interval '168 hours' where user_id='71000000-0000-0000-0000-000000000003' and status='rejected';
select lives_ok($$select pg_temp.app(3,'submit',pg_temp.evidence())$$,'at seven day boundary accepted');
select is((select count(*)::int from private.critic_applications where user_id='71000000-0000-0000-0000-000000000003'),3,'history retained new identity');
select throws_ok($$select pg_temp.app(2,'submit',pg_temp.evidence()||jsonb_build_object('organization','xx'))$$,'23514',null,'invalid evidence refused');
select throws_ok($$select pg_temp.app(2,'submit',pg_temp.evidence()||jsonb_build_object('experience',repeat('🦊',39)))$$,'23514',null,'invalid evidence refused');
select throws_ok($$select pg_temp.app(2,'submit',pg_temp.evidence()||jsonb_build_object('sample',repeat('x',5001)))$$,'23514',null,'invalid evidence refused');
select throws_ok($$select pg_temp.app(2,'submit',pg_temp.evidence()||'{"links":["http://example.com"]}'::jsonb)$$,'22023',null,'invalid evidence refused');
select throws_ok($$select pg_temp.app(2,'submit',pg_temp.evidence()||'{"links":[null]}'::jsonb)$$,'22023',null,'invalid evidence refused');
select throws_ok($$select pg_temp.app(2,'submit',pg_temp.evidence()||'{"user_id":"fake"}'::jsonb)$$,'22023',null,'invalid evidence refused');
set local role anon;
select throws_ok($$select * from private.critic_applications$$,'42501',null,'anon denied select private.critic_applications');
select throws_ok($$insert into private.critic_applications(id) values(gen_random_uuid())$$,'42501',null,'anon denied insert private.critic_applications');
select throws_ok($$update private.critic_applications set id=gen_random_uuid()$$,'42501',null,'anon denied update private.critic_applications');
select throws_ok($$delete from private.critic_applications$$,'42501',null,'anon denied delete private.critic_applications');
select throws_ok($$select * from private.application_notices$$,'42501',null,'anon denied select private.application_notices');
select throws_ok($$insert into private.application_notices(id) values(gen_random_uuid())$$,'42501',null,'anon denied insert private.application_notices');
select throws_ok($$update private.application_notices set id=gen_random_uuid()$$,'42501',null,'anon denied update private.application_notices');
select throws_ok($$delete from private.application_notices$$,'42501',null,'anon denied delete private.application_notices');
select throws_ok($$select private.critic_application_operation(gen_random_uuid(),gen_random_uuid(),'own-history','{"page":1}')$$,'42501',null,'anon cannot execute gateway');
reset role;
set local role authenticated;
select throws_ok($$select * from private.critic_applications$$,'42501',null,'authenticated denied select private.critic_applications');
select throws_ok($$insert into private.critic_applications(id) values(gen_random_uuid())$$,'42501',null,'authenticated denied insert private.critic_applications');
select throws_ok($$update private.critic_applications set id=gen_random_uuid()$$,'42501',null,'authenticated denied update private.critic_applications');
select throws_ok($$delete from private.critic_applications$$,'42501',null,'authenticated denied delete private.critic_applications');
select throws_ok($$select * from private.application_notices$$,'42501',null,'authenticated denied select private.application_notices');
select throws_ok($$insert into private.application_notices(id) values(gen_random_uuid())$$,'42501',null,'authenticated denied insert private.application_notices');
select throws_ok($$update private.application_notices set id=gen_random_uuid()$$,'42501',null,'authenticated denied update private.application_notices');
select throws_ok($$delete from private.application_notices$$,'42501',null,'authenticated denied delete private.application_notices');
select throws_ok($$select private.critic_application_operation(gen_random_uuid(),gen_random_uuid(),'own-history','{"page":1}')$$,'42501',null,'authenticated cannot execute gateway');
reset role;
set local role service_role;
select throws_ok($$select * from private.critic_applications$$,'42501',null,'service_role denied select private.critic_applications');
select throws_ok($$insert into private.critic_applications(id) values(gen_random_uuid())$$,'42501',null,'service_role denied insert private.critic_applications');
select throws_ok($$update private.critic_applications set id=gen_random_uuid()$$,'42501',null,'service_role denied update private.critic_applications');
select throws_ok($$delete from private.critic_applications$$,'42501',null,'service_role denied delete private.critic_applications');
select throws_ok($$select * from private.application_notices$$,'42501',null,'service_role denied select private.application_notices');
select throws_ok($$insert into private.application_notices(id) values(gen_random_uuid())$$,'42501',null,'service_role denied insert private.application_notices');
select throws_ok($$update private.application_notices set id=gen_random_uuid()$$,'42501',null,'service_role denied update private.application_notices');
select throws_ok($$delete from private.application_notices$$,'42501',null,'service_role denied delete private.application_notices');
select throws_ok($$select private.critic_application_operation(gen_random_uuid(),gen_random_uuid(),'own-history','{"page":1}')$$,'42501',null,'service_role cannot execute gateway');
reset role;
select lives_ok($$select pg_temp.app(7,'submit',pg_temp.evidence())$$,'self-resolution fixture submitted');
update private.authz set role='admin' where user_id='71000000-0000-0000-0000-000000000007';
select throws_ok($$select pg_temp.app(7,'resolve',pg_temp.decision(7,'approved'))$$,'42501',null,'self-resolution forbidden after authority changed');
select throws_ok($$select pg_temp.app(7,'cancel',pg_temp.decision(7,'approved')-'decision')$$,'42501',null,'self-cancellation forbidden');
select lives_ok($$select pg_temp.app(8,'submit',pg_temp.evidence())$$,'missing-authority fixture submitted');
delete from private.authz where user_id='71000000-0000-0000-0000-000000000008';
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(8,'approved'))$$,'23505',null,'missing target authority cannot resolve');
select throws_ok($$update private.critic_applications set status='rejected',version=2,resolved_at=null,reason=null where user_id='71000000-0000-0000-0000-000000000008'$$,'23514',null,'terminal null resolution forbidden');
update private.authz set critic_verified=true where user_id='71000000-0000-0000-0000-000000000002';
select ok((pg_temp.app(2,'own-history','{"page":1}')->>'eligible')::boolean,'user with prior seal is eligible');
select lives_ok($$select pg_temp.app(2,'submit',pg_temp.evidence())$$,'verified user may submit');
select ok((select expected_verified from private.critic_applications where user_id='71000000-0000-0000-0000-000000000002' and status='pending'),'actual true seal captured');
select is((select role::text||':'||critic_verified::text from private.authz where user_id='71000000-0000-0000-0000-000000000002'),'user:true','submission preserves user authority and seal');
update private.authz set critic_verified=false where user_id='71000000-0000-0000-0000-000000000002';
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(2,'approved'))$$,'23505',null,'changed prior true seal prevents resolution');
select lives_ok($$select pg_temp.app(5,'cancel',pg_temp.decision(2,'approved')-'decision')$$,'changed prior seal permits cancellation');
update private.authz set critic_verified=true where user_id='71000000-0000-0000-0000-000000000002';
select lives_ok($$select pg_temp.app(2,'submit',pg_temp.evidence())$$,'verified user may resubmit after cancellation');
select lives_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(2,'approved'))$$,'unchanged true seal snapshot may be approved');
select is((select role::text||':'||critic_verified::text from private.authz where user_id='71000000-0000-0000-0000-000000000002'),'critic:true','prior true seal approval grants critic role');
select is((select reputation_score::int from public.profiles where id='71000000-0000-0000-0000-000000000002'),0,'submission and approval never grant reputation');
select ok(not private.application_cooldown_elapsed('2026-11-01T00:00:00Z'::timestamptz+interval '168 hours','2026-11-07T23:59:59.999999Z'),'cooldown immediately before exact 168h denied');
select ok(private.application_cooldown_elapsed('2026-11-01T00:00:00Z'::timestamptz+interval '168 hours','2026-11-08T00:00:00Z'),'cooldown exact equality accepted');
select ok(private.application_cooldown_elapsed('2026-11-01T00:00:00Z'::timestamptz+interval '168 hours','2026-11-08T00:00:00.000001Z'),'cooldown immediately after accepted');
select is(private.application_trim(U&'\000A\00A0\FEFFtext\2028\3000'),'text','SQL trim matches JS Unicode trim');
select throws_ok($$select pg_temp.app(2,'submit',pg_temp.evidence()||jsonb_build_object('experience',repeat(E'\n',40)))$$,'42501',null,'verified critic still ineligible before evidence validation');
select is((pg_temp.app(5,'admin-get',jsonb_build_object('id',(select id from private.critic_applications where user_id='71000000-0000-0000-0000-000000000001')))->>'status'),'approved','admin reads exact persisted terminal result');
select ok((pg_temp.app(5,'admin-get',jsonb_build_object('id',(select id from private.critic_applications where user_id='71000000-0000-0000-0000-000000000001')))->'current_authority'->>'critic_verified')::boolean,'admin reads current seal');
select ok((pg_temp.app(5,'admin-history','{"page":1}')->>'total')::int>1,'admin history includes terminal applications');
select throws_ok($$select pg_temp.app(4,'admin-history','{"page":1}')$$,'42501',null,'moderator denied admin history');
select throws_ok($$select pg_temp.app(3,'admin-get',jsonb_build_object('id',(select id from private.critic_applications where user_id='71000000-0000-0000-0000-000000000001')))$$,'42501',null,'critic denied admin exact read');
select ok(not has_function_privilege('service_role','private.application_cooldown_elapsed(timestamptz,timestamptz)','execute'),'service role cannot inject clock through private predicate');
select ok(position('private.application_cooldown_elapsed(next_allowed,clock_timestamp())' in pg_get_functiondef('private.critic_application_operation(uuid,uuid,text,jsonb)'::regprocedure))>0,'submission really uses tested predicate with server clock');
select throws_ok($$select pg_temp.app(9,'submit',pg_temp.evidence()||jsonb_build_object('experience',repeat(E'\n',40)))$$,'23514',null,'SQL rejects newline-only experience');
select throws_ok($$select pg_temp.app(9,'submit',pg_temp.evidence()||jsonb_build_object('sample',repeat(U&'\FEFF',40)))$$,'23514',null,'SQL rejects Unicode-only sample');
select throws_ok($$select pg_temp.app(9,'submit',pg_temp.evidence()||jsonb_build_object('organization',repeat(U&'\00A0',3)))$$,'23514',null,'SQL rejects Unicode-only organization');
select lives_ok($$select pg_temp.app(9,'submit',pg_temp.evidence()||jsonb_build_object('organization',U&'\000A\00A0Independiente\FEFF'))$$,'SQL normalizes valid Unicode evidence');
select is((select organization from private.critic_applications where user_id='71000000-0000-0000-0000-000000000009'),'Independiente','normalized storage accepted by DTO');
select throws_ok($$select pg_temp.app(5,'resolve',pg_temp.decision(9,'rejected')||jsonb_build_object('reason',repeat(E'\n',10)))$$,'22023',null,'SQL rejects whitespace-only reason');
select ok(private.valid_application_links('["HTTPS://example.com/evidence"]'::jsonb),'HTTPS scheme is case insensitive');
select * from finish();
rollback;
